def test_intake_issue():
    def with_deque(iterable, n):
        iterator = iter(iterable)
        window = deque(islice(iterator, n - 1), maxlen=n)
        for x in iterator:
            window.append(x)
            yield tuple(window)

    def with_list(iterable, n):
        iterator = iter(iterable)
        window = list(islice(iterator, n - 1))
        for x in iterator:
            window.append(x)
            yield tuple(window)
            del window[0]

    def with_tees(iterable, n):
        iterators = tee(iterable, n)
        for i, iterator in enumerate(iterators):
            next(islice(iterator, i, i), None)
        return zip(*iterators)

    funcs = [
        with_deque,
        with_list,
        with_tees,
    ]

    from time import perf_counter as time
    from statistics import mean, stdev
    from itertools import tee, islice
    from collections import deque
    import sys
    import random

    # Correctness
    for m in range(20):
        data = range(m)
        for n in range(1, 30):
            expect = list(funcs[0](data, n))
            for f in funcs:
                result = list(f(data, n))
                assert result == expect, (data, n, f.__name__, expect, result)

    # Speed
    data = [None] * 10_000
    ns = sorted({
        n
        for i in range(31)
        for n in [round(10**(i/10))]
        if n >= 3
    })
    def shuffled(xs):
        return random.sample(xs, len(xs))

    times = {f: {n: [] for n in ns} for f in funcs}
    for i in range(30):
        print(i)
        for n in shuffled(ns):
            for f in shuffled(funcs):
                t0 = time()
                for w in f(data, n):
                    pass
                t = time() - t0
                times[f][n].append(t)

    # fastest time for each (function,n) pair
    times = {f.__name__.removeprefix('with_'): [min(times[f][n]) for n in ns]
        for f in funcs
    }

    # Times in percent of the deque times
    times = {
        name: [t / td * 100 for t, td in zip(times[name], times['deque'])]
        for name in times
    }

    # Plotting
    import matplotlib.pyplot as plt
    for name, y in times.items():
        plt.semilogx(ns, y, label=name)
    plt.ylim(0, 150)
    plt.title('sliding_window([None]*10000, n)', weight='bold')
    plt.xlabel('n', weight='bold')
    plt.ylabel('time in % of deque solution time', weight='bold')
    plt.legend(loc='upper left')
    plt.savefig('sliding_window.png', dpi=200)

    print(sys.version)

